const $=id=>document.getElementById(id);let stream=null,url=null,blob=null,ticket=0,pending=false,view=false;
const say=text=>$('cameraMessage').textContent=text;
function paint(){const live=!!stream;$('cameraVideo').hidden=!live;$('cameraPhoto').hidden=live||!url;$('cameraEmpty').hidden=live||!!url;$('cameraShotWrap').hidden=!url||!live;$('cameraDownload').hidden=!url;$('cameraStart').disabled=pending;$('snapshot').disabled=pending;$('snapshotLabel').textContent=live?'Fotoğraf çek':'Kamerayı aç';$('snapshot').setAttribute('aria-label',live?'Fotoğraf çek':'Kamerayı aç');$('dockStatus').textContent=pending?'Hazırlanıyor…':live?'● Canlı kamera':url?'Fotoğraf':'Kamera kapalı';$('shutterDock').hidden=!view;document.documentElement.classList.toggle('has-capture-bar',view);}
function stop(){ticket++;stream?.getTracks().forEach(t=>t.stop());stream=null;$('cameraVideo').srcObject=null;pending=false;paint();}
function clear(){stop();if(url)URL.revokeObjectURL(url);url=null;blob=null;$('cameraPhoto').removeAttribute('src');$('cameraShot').removeAttribute('src');paint();}
async function showPhoto(value){if(url)URL.revokeObjectURL(url);blob=value;url=URL.createObjectURL(value);$('cameraPhoto').src=url;$('cameraShot').src=url;paint();}
async function start(){if(pending)return;stop();const id=++ticket;pending=true;paint();say('Kamera izni bekleniyor…');try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Kamera için HTTPS ve desteklenen tarayıcı gerekir. Fotoğraf yükleyebilirsin.');const next=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1600}},audio:false});if(id!==ticket){next.getTracks().forEach(t=>t.stop());return;}stream=next;$('cameraVideo').srcObject=next;await $('cameraVideo').play();if(id!==ticket)return;next.getVideoTracks()[0].addEventListener('ended',()=>{if(stream===next){stop();say('Kamera kapandı. Yeniden açabilirsin.');}},{once:true});say('Canlı görüntü açık. Fotoğraf çekebilir veya madde adını yazarak kütüphaneyi araştırabilirsin.');}catch(e){if(id===ticket){stream?.getTracks().forEach(t=>t.stop());stream=null;$('cameraVideo').srcObject=null;say(e.name==='NotAllowedError'?'Kamera izni verilmedi. Tarayıcı iznini aç veya fotoğraf yükle.':e.message);}}finally{if(id===ticket){pending=false;paint();}}}
$('cameraStart').onclick=start;$('cameraStop').onclick=()=>{stop();say('Canlı kamera kapalı. Çektiğin fotoğraf bu sayfada kalır.');};
$('snapshot').onclick=async()=>{if(!stream){await start();return;}if(pending)return;const id=ticket;pending=true;paint();try{const v=$('cameraVideo');if(!v.videoWidth)throw new Error('Kamera görüntüsü henüz hazır değil.');const c=document.createElement('canvas'),ratio=Math.min(1,1600/Math.max(v.videoWidth,v.videoHeight));c.width=Math.round(v.videoWidth*ratio);c.height=Math.round(v.videoHeight*ratio);c.getContext('2d').drawImage(v,0,0,c.width,c.height);const image=await new Promise(r=>c.toBlob(r,'image/jpeg',.92));if(id!==ticket)return;if(!image)throw new Error('Fotoğraf alınamadı.');await showPhoto(image);say('Fotoğraf çekildi. Canlı görüntü açık; son çekim aşağıda görünüyor.');}catch(e){if(id===ticket)say(e.message);}finally{if(id===ticket){pending=false;paint();}}};
$('cameraUpload').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(!file.type.startsWith('image/')||file.size>12*1024*1024){say('En fazla 12 MB boyutunda bir görüntü seç.');return;}clear();const id=ticket;pending=true;paint();try{const test=new Image(),tmp=URL.createObjectURL(file);try{test.src=tmp;await test.decode();}finally{URL.revokeObjectURL(tmp);}if(id!==ticket)return;await showPhoto(file);say('Fotoğraf açıldı. Fotoğraf ve hesap bilgileri sunucuya gönderilmez.');}catch{if(id===ticket)say('Görüntü okunamadı. JPEG, PNG veya WebP dene.');}finally{if(id===ticket){pending=false;paint();}}};
$('cameraDelete').onclick=()=>{clear();say('Fotoğraf silindi.');};
$('cameraDownload').onclick=()=>{if(!url)return;const a=document.createElement('a');a.href=url;a.download='liquid-lens-fotograf.'+({'image/png':'png','image/jpeg':'jpg','image/webp':'webp','image/gif':'gif','image/avif':'avif'}[blob?.type]||'img');a.click();};
$('backToCamera').onclick=()=>$('cameraStage').scrollIntoView({behavior:'smooth',block:'center'});
$('cameraLookup').onsubmit=e=>{e.preventDefault();window.dispatchEvent(new CustomEvent('open-library',{detail:{query:$('cameraName').value.trim()}}));};
window.addEventListener('viewchange',e=>{view=e.detail==='camera';if(!view)stop();paint();});
window.addEventListener('accountchange',clear);document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});window.addEventListener('pagehide',clear);paint();

const upload=document.querySelector('#view-camera .upload');upload.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();document.getElementById('cameraUpload').click();}};
